from pages import *
from fig import *
i=1
D=lambda **k: devi(items=('trident','discus','sword','conch','bow','bell','lotus','mace'),**k)
COV=covart('The eight-armed Devī on her lion, holding trident, discus, sword, conch and other weapons, facing the buffalo demon Mahiṣa, with gods watching from above',
  g(150,200,1.15,beast('lion'))+g(150,170,1.1,D())+g(330,200,1.1,beast('buffalo'),flip=True)+g(370,90,.7,demon('#3a3a40'))+''.join(g(40+k*30,60,.45,god(c)) for k,c in enumerate(['#1d6fb8','#c0392b','#e0a800'])))
def sc(inner,bg='#fff3cf'): return (inner,bg)
S1=strip('Three panels: Mahiṣa on Indra’s throne; the gods wandering on earth; the gods telling Viṣṇu and Śiva',
 [sc(g(72,150,1,'<rect x="-30" y="-20" width="60" height="20" fill="#e0a800"/>')+g(72,132,.9,demon('#3a3a40'))+g(50,80,.5,beast('buffalo')),'#e9e3f5'),
  sc(ground(144,170,140,'#cfe0b8')+''.join(g(30+k*40,150,.7,god(c)) for k,c in enumerate(['#1d6fb8','#c0392b','#2a9d6f']))),
  sc(g(45,150,.75,god('#1d6fb8'))+g(105,150,.75,shiva())+g(72,40,.7,'<path d="M-20 0 q20 -24 40 0" fill="#ff8c1a"/>'),'#dfe9f6')],
 ['Mahiṣa takes heaven','the gods are driven out','they go to Viṣṇu and Śiva'])
S2=strip('Three panels: beams of fiery light coming out of the gods; the light joining into one blaze; a goddess standing in the light',
 [sc(''.join(g(28+k*44,150,.6,god(c)) for k,c in enumerate(['#1d6fb8','#c0392b','#e0a800']))+''.join(f'<path d="M{28+k*44} 100 L72 30" stroke="#ff8c1a" stroke-width="5"/>' for k in range(3)),'#2a1d3a'),
  sc(g(72,95,1.2,sun(26)),'#2a1d3a'),
  sc(g(72,160,.85,D()),'#2a1d3a')],
 ['light pours from the gods','it gathers like a mountain of fire','and becomes a woman'])
S3=strip('Three panels: the Devī on her lion roaring; Mahiṣa’s generals attacking; the generals fallen',
 [sc(g(72,160,.8,beast('lion'))+g(72,128,.6,D())),sc(''.join(g(28+k*44,160,.6,demon(c)) for k,c in enumerate(['#2a6a3a','#6a2a3a','#3a3a6a']))),sc(ground(144,170,140,'#e9d6c0')+g(72,140,.7,'<path d="M-40 0 h80" stroke-width="3"/>')+g(72,120,.6,'<g transform="rotate(90)">'+demon()+'</g>'))],
 ['her roar fills the sky','Cikṣura, Cāmara and the rest','one by one they fall'])
S4=strip('Three panels: a buffalo, then a lion, then an elephant, the shapes Mahiṣa takes',
 [sc(g(72,130,1,beast('buffalo'))),sc(g(72,130,1,beast('lion'))),sc(g(72,150,.8,elephant(False)),'#e9e3f5')],['a buffalo…','…a lion, a man with a sword…','…an elephant, then a buffalo again'])
pages=[foreword(i,[
 'In '+link(0,'Part 1')+' we drew the map of Navarātri. Now the story behind it. Every Navarātri points back to one great victory: the <b>Devī</b> slaying <b>Mahiṣāsura</b>, the buffalo demon who had taken heaven from the gods.',
 'The story is told in the <b>Devī Māhātmya</b> (chapters 2 to 4), the scripture recited through the nine nights. Our <a href="/devi/devi-mahatmya/part-7/">Devī Māhātmya Parts 7 to 9</a> go through it verse by verse; here we tell it as one story, then ask what it means, and why Mysuru carries its name.'],
 [('z','Is Mahiṣa just a buffalo?'),('b','He is a demon who can take any form. The buffalo is his favourite, and his name: <i>mahiṣa</i> means buffalo.')]),
 glance([('Source','Devī Māhātmya, chapters 2–4 (the middle story, <i>madhyama carita</i>)'),('Presiding form','Mahālakṣmī, the Devī of the middle story'),('Enemy','Mahiṣāsura, the buffalo demon, and his generals'),('The Devī’s birth','From the gathered anger and light of all the gods'),('Her mount','A lion, given by Himavat, the mountain'),('The end','She beheads Mahiṣa; the gods praise her (the Śakrādi Stuti)'),('Her promise','To come again whenever she is remembered in distress')],
  svg(560,150,'The Devī on her lion standing over the defeated buffalo',g(250,140,1,beast('lion'))+g(250,110,.8,D())+g(400,140,.9,'<g transform="rotate(10)">'+beast('buffalo')+'</g>'))),
 story('defeat','HEAVEN LOST','Devī Māhātmya 2.1–8',S1,'Long ago the gods and the demons fought a war that lasted a hundred years.',[
  'Mahiṣāsura led the demons; Indra led the gods. After a hundred years the gods were beaten.','Mahiṣa took Indra’s throne and made himself lord of heaven. He took the places of the Sun, the Moon, Agni, Vāyu, Yama and Varuṇa as well.','The gods, driven out, wandered the earth like mortals.','Led by Brahmā, they went to Viṣṇu and Śiva and told them everything.','As they listened, Viṣṇu and Śiva grew furious, their faces twisted with anger.'],
  [('z','Why didn’t the gods just fight harder?'),('b','They had fought for a hundred years. The story is saying: some troubles are beyond what even the strong can solve alone.')],'Mahiṣa takes heaven; the gods come to Viṣṇu and Śiva <b>for help</b>.'),
 story('born','THE GODDESS BORN OF LIGHT','Devī Māhātmya 2.9–18',S2,'Then something happened that had never happened before.',[
  'From Viṣṇu’s face, full of anger, came a great light; from Śiva and Brahmā came lights too.','Light poured from the bodies of Indra and all the other gods, and all of it ran together.','The gods saw it as a mountain of fire, filling every direction with flame.','That light, born of all the gods, became a woman, her radiance filling the three worlds.','Each part of her came from a god: her face from Śiva, her arms from Viṣṇu, her hair from Yama, her feet from Brahmā.'],
  [('z','So she is made of all the gods?'),('b','Their power, gathered into one. Many read it the other way round too: the gods’ powers were always hers, and now she shows herself.')],'Not one god’s power but <b>all of them together</b>: that is the Devī.'),
 cards('gifts','THE GIFTS OF THE GODS','Devī Māhātmya 2.19–30: every god gives her a weapon',svg(560,190,'The Devī with many arms holding the weapons given by the gods, with labels for the trident, discus, conch, bow, thunderbolt and bell',g(280,180,1.35,D())+lab(130,60,'Śiva’s trident')+lab(130,110,'Viṣṇu’s discus')+lab(130,160,'Varuṇa’s conch')+lab(440,60,'Vāyu’s bow')+lab(440,110,'Indra’s vajra and bell')+lab(440,160,'Himavat’s lion')),[
  ('🔱','Śiva and Viṣṇu','Śiva drew a trident out of his own and gave it to her; Viṣṇu brought a discus out of his own discus.'),
  ('⚡','Indra, Varuṇa, Agni, Vāyu','Indra gave a thunderbolt and the bell from his elephant Airāvata; Varuṇa a conch and a noose; Agni a spear; Vāyu a bow and quivers of arrows.'),
  ('📿','Brahmā, Yama, Kāla, Sūrya','Brahmā gave a rosary and water pot; Yama his staff; Kāla (Time) a sword and shield; the Sun filled her pores with his rays.'),
  ('🦁','Himavat and the rest','The Ocean gave a necklace and jewels; Viśvakarmā an axe and armour; Kubera a cup of drink; Śeṣa a serpent necklace; and Himavat, the mountain, gave her the <b>lion</b>.')],
  [('z','Why does she need so many weapons?'),('b','Because each god gives what he has. She carries the whole of heaven’s strength in her hands.')],'Every god gives his best weapon; <b>the lion comes from the mountain</b>.'),
 story('battle','THE BATTLE','Devī Māhātmya 2.31–3.19',S3,'She laughed aloud, and her roar shook the worlds.',[
  'Mahiṣa heard the sound and ran toward it with all his army: “What is this?”','He saw her, her light filling the three worlds, her feet bending the earth, her crown scraping the sky.','His generals Cikṣura, Cāmara, Udagra, Mahāhanu, Bāṣkala and many more attacked with thousands of chariots, elephants and horses.','She cut down their weapons as if in play; from her sighs, armies of her own sprang up and fought beside her. Her lion, shaking its mane, roamed the field.','One after another the generals fell, until only Mahiṣa himself was left.'],
  [('z','She was smiling while fighting?'),('b','The text says she fought “as if in play”. For the Mother, this battle is not a struggle. The struggle is ours; she is simply putting things right.')],'Her roar starts the battle; <b>his whole army falls</b>.'),
 story('shapes','THE MANY SHAPES OF MAHIṢA','Devī Māhātmya 3.20–41',S4,'Then Mahiṣa came himself, in his own buffalo form.',[
  'He charged her troops, tossing them with his horns, lashing with his tail; mountains and clouds were thrown about.','She caught him in her noose. He became a lion; she cut off its head, and he came out as a man with a sword.','She shot the man with arrows; he became a great elephant and dragged her lion. She cut off its trunk.','He became a buffalo again. She drank the divine drink and laughed: “Roar, roar for a moment, fool, while I drink.”','She leapt on him, pressed his neck with her foot and struck with her spear. He began to come out of his own mouth, and with her great sword she cut off his head.'],
  [('z','Why does he keep changing?'),('b','Many read Mahiṣa as the ego: chase it out of one shape and it slips into another. Only when she pins it down with her foot does it finally end.')],'Buffalo, lion, man, elephant: <b>she follows every disguise to the end</b>.'),
 reading('praise','THE GODS’ HYMN AND HER PROMISE','Devī Māhātmya 4: the Śakrādi Stuti',svg(560,170,'The gods led by Indra standing with folded hands before the Devī, who raises her hand in blessing',''.join(g(60+k*55,160,.8,god(c)) for k,c in enumerate(['#1d6fb8','#c0392b','#e0a800','#2a9d6f']))+g(430,165,1,devi(items=('abhaya','lotus','trident','discus'))) ),[
  '<b>Praise.</b> When Mahiṣa fell, the gods led by Indra (Śakra) bowed and sang a long hymn, the <b>Śakrādi Stuti</b>. They praise her as the power behind the whole world, as good fortune in the homes of the good and misfortune in the homes of the wicked. Our <a href="/devi/devi-mahatmya/part-9/">Devī Māhātmya Part 9</a> reads it verse by verse.',
  '<b>A boon.</b> Pleased, the Devī offered them a boon. The gods asked only this: that whenever they remembered her in danger, she would come and destroy their troubles, and that she would bless anyone who praised her with this hymn.',
  '<b>Her promise.</b> She agreed, and vanished. This promise is the heart of Navarātri: the Mother who came once comes again whenever she is called. Every recitation in the nine nights is a calling.',
  '<b>Why it is read now.</b> Because the story ends in a promise, it is read at the time of year set aside for the Goddess, and above all on the ninth and tenth days, when the victory is remembered.'],
  [('z','So she isn’t gone after the fight?'),('b','She vanished, but she promised to return. That is why the festival repeats every year.')],'The gods’ only wish: <b>“come whenever we remember you”</b>. She said yes.'),
 reading('meaning','WHAT THE STORY MEANS','Readings across the tradition',svg(560,160,'A buffalo shape dissolving into a small flame held in a hand, showing the reading of the demon as ego and the Goddess as awakened power',g(140,140,1,beast('buffalo'))+'<path d="M220 100 h80" stroke="#111" stroke-width="3" marker-end=""/><path d="M300 100 l-10 -6 v12z" fill="#111"/>'+g(400,140,1.3,lamp('#c0392b'))+lab(140,155,'pride, inertia, ego')+lab(400,155,'light within')),[
  '<b>The plain reading.</b> The story is first of all what it says: the gods were helpless and the Mother saved them. Devotees take it as a promise for their own troubles.',
  '<b>The inner reading.</b> Many teachers read Mahiṣa, the buffalo, as heaviness and pride: inertia (<i>tamas</i>) wearing the crown of heaven. The Devī, made of all the gods’ light, is the awakened power that alone can overcome it.',
  '<b>The shape-changing.</b> The buffalo that becomes a lion, a man and an elephant is read as the ego slipping from one disguise to the next. The Devī’s foot on his neck is the moment it can no longer escape.',
  '<b>One power, many gods.</b> Philosophers in the Śākta tradition read the birth from all the gods’ light as a statement that the Goddess is the single power (<i>śakti</i>) behind every god. These are interpretations; the text itself tells the story.'],
  [('z','Which reading is right?'),('b','They stack, like floors of one house. The story, then the meaning inside, then the philosophy. You can live on any floor.')],'Outer story, inner battle: <b>the same victory twice</b>.'),
 reading('mysuru','CĀMUṆḌĪ AND MYSURU','Why the city carries the buffalo’s name',svg(560,200,'Cāmuṇḍī Hill with its temple tower on top, a large statue of Mahiṣāsura with a sword and snake halfway, and the city below',ground(560,200,170,'#cfe0b8')+'<path d="M60 170 L240 50 L420 170z" fill="#8a9a6a" stroke="#111" stroke-width="2.5"/>'+g(240,62,.6,'<path d="M-20 0 h40 l-6 -40 h-28z" fill="#e8c06a"/><circle cy="-46" r="4" fill="#e0a800"/>')+g(330,140,.7,demon('#2a6a3a'))+g(345,110,.4,sword())+''.join(f'<rect x="{x}" y="174" width="18" height="16" fill="#f3e3c3" stroke="#111"/>' for x in range(440,560,24))+lab(240,30,'Cāmuṇḍeśvarī temple')+lab(330,160,'Mahiṣāsura')+lab(500,198,'Mysuru')),[
  '<b>The name.</b> A local tradition holds that the city’s old name, <b>Mahiṣūru</b>, “buffalo town”, comes from Mahiṣāsura, who ruled here until the Devī slew him on the hill above. Mysuru is the later form.',
  '<b>Cāmuṇḍeśvarī.</b> On that hill stands the temple of <b>Cāmuṇḍeśvarī</b>, the Devī as Mahiṣa’s slayer and the family deity of the Woḍeyars. A great statue of Mahiṣāsura, sword in hand, stands on the hill road. Our <a href="/temples-of-india/around-mysuru/chamundeshwari/">Around Mysuru article on Cāmuṇḍī Hill</a> tells the temple’s story.',
  '<b>The name Cāmuṇḍā.</b> In the Devī Māhātmya the name <b>Cāmuṇḍā</b> is earned later, in chapter 7, when Kālī slays the demons Caṇḍa and Muṇḍa (<a href="/devi/devi-mahatmya/part-12/">Part 12</a> of our series). At Mysuru, tradition joins the two victories in one goddess.',
  '<b>The festival.</b> That is why Mysuru keeps Navarātri as its own festival: the Goddess of the story is the Goddess of the hill. On Vijayadaśamī her golden image rides on an elephant through the city ('+link(15,'Part 16')+').'],
  [('z','So the demon is from Mysuru?'),('b','So the local story says. Scholars debate the name; devotees don’t. Either way, the city is proud of its Goddess.')],'Mahiṣūru, Cāmuṇḍī Hill: <b>the story lives on the map</b>.'),
 cards('more','OTHER STORIES OF THE SEASON','Not only Mahiṣa',svg(560,170,'Four small scenes: Rāma with his bow, a śamī tree with weapons, the Devī facing two demon brothers, and Umā returning home with her children',g(80,160,.9,person('#1d6fb8'))+g(108,130,.6,bow())+g(210,160,.9,shami())+g(350,160,.8,devi(items=('sword','trident')))+g(410,160,.6,demon())+g(440,160,.6,demon('#6a2a3a'))+g(510,160,.8,devi(items=('lotus',),sari='#e0a800'))+g(540,160,.6,child())),[
  ('🏹','Rāma and Rāvaṇa','The tenth day remembers Rāma’s victory over Rāvaṇa. Bengal’s tradition says Rāma first worshipped Durgā in autumn to win it.'),
  ('🌳','The Pāṇḍavas and the śamī','The Pāṇḍavas hid their weapons in a śamī tree in their year in disguise and took them back for the battle: hence śamī worship on Vijayadaśamī.'),
  ('⚔️','Śumbha and Niśumbha','The last story of the Devī Māhātmya: the demon brothers, Caṇḍa and Muṇḍa, Raktabīja. Kālī and Cāmuṇḍā belong here, and the seventh and eighth nights often recall it.'),
  ('🏡','Umā comes home','In Bengal the Goddess is also the daughter Umā visiting her parents with Gaṇeśa, Kārttikeya, Lakṣmī and Sarasvatī for four days.')],
  [('z','So many stories for one festival?'),('b','A great festival collects stories the way a river collects streams. Part 15 tells the Rāma and Pāṇḍava ones in full.')],'Mahiṣa first, then Rāma, the Pāṇḍavas and Umā: <b>one season, many victories</b>.'),
 end(i,['<b>Defeat.</b> Mahiṣa beat the gods and took heaven.','<b>Birth.</b> The gods’ anger and light joined into the Devī.','<b>Gifts.</b> Every god gave a weapon; the mountain gave the lion.','<b>Victory.</b> She followed Mahiṣa through every shape and beheaded him.','<b>Promise.</b> She will come whenever she is remembered: the reason for Navarātri.'],
  'Part 3 is practical: how the nine nights actually begin at home, with the kalaśa, the barley and the lamp that is not allowed to go out.','The story behind it'),
 sources([('Text:','Devī Māhātmya chapters 2–4 (Mārkaṇḍeya Purāṇa 82–84), following our <a href="/devi/devi-mahatmya/">Devī Māhātmya series</a> (edition: devimahatmyam.aurobharati.in); names of generals and gifts as given there.'),('Mysuru:','Wikipedia, “Mysore Dasara” and “Chamundeshwari Temple” (Mahiṣūru tradition, Mahiṣāsura statue). Our Around Mysuru: Cāmuṇḍeśvarī article.'),('Readings:','The inner reading of Mahiṣa as tamas/ego is a common teacher’s interpretation, not part of the text.')],
  'the derivation of “Mysuru” from Mahiṣāsura (a local tradition; scholars differ); Rāma’s autumn worship (Bengali tradition).','Devī Māhātmya numbered by chapter and verse as in the standard Saptaśatī.')]
build(i,'PART 2 OF 16 · THE BUFFALO DEMON · THE GODS’ LIGHT',COV,'The Devī and Mahiṣa',
 'The story told <b>in order</b>, from heaven lost to the Goddess born of the gods’ light, the battle and Mahiṣa’s many shapes, then <b>what it means</b> and why Mysuru carries the buffalo’s name.',
 'The story behind Navarātri: how Mahiṣāsura took heaven, how the Devī was born from the gods’ light, the gifts of the gods, the battle, Mahiṣa’s many shapes, the gods’ hymn and her promise, and Cāmuṇḍī Hill in Mysuru. Part 2 of the illustrated Navarātri and Dasarā series.',pages)
print('ok')
